shader_type canvas_item;

uniform sampler2D screen_texture : hint_screen_texture;
uniform float shift : hint_range(-0.2, 0.2) = 0.0;

void fragment() {
	vec2 spot = SCREEN_UV + vec2(shift, 0.0);
	COLOR.rgb = texture(screen_texture, spot).rgb;
}

shader_type canvas_item;

uniform sampler2D screen_texture : hint_screen_texture;
uniform float amount : hint_range(0.0, 0.05) = 0.01;

void fragment() {
	float wave = sin(SCREEN_UV.y * 60.0);
	vec2 spot = SCREEN_UV + vec2(wave * amount, 0.0);
	COLOR.rgb = texture(screen_texture, spot).rgb;
}

